"""Cash generated by priced sales and receipts, less explicit cash transfers.

A deposit changes cash on hand, not net worth. No inventory cost or unstated
opening balance is invented, and account-balance questions use other models.
"""

from collections import Counter, defaultdict
from . import consumer
from ..answer import Answer, AnswerAssumption
from ..evaluate import evaluate
from ..model import BatchEvidence, EventTime
from ..numeric_evidence import audit_numeric_mentions
from ..rate_calculation import convert_units
from ..reference_identity import reference_from_unit
from ..source_coverage import uncovered_document_units


@consumer(
    "cash-transaction-balance",
    applicable=lambda store: any(
        row.kind == "cash-deposit" for row in store.by_kind(BatchEvidence)
    ),
)
def consume(ctx):
    def decline(reason):
        return Answer("decline", None, reason)

    rows = sorted(
        ctx.store.by_kind(BatchEvidence),
        key=lambda r: (r.provenance.sentence, r.position),
    )
    quotes = [r for r in rows if r.kind == "cash-sale-quote"]
    sales = [r for r in rows if r.kind == "cash-sale"]
    receipts = [r for r in rows if r.kind == "cash-receipt"]
    deposits = [r for r in rows if r.kind == "cash-deposit"]
    who = reference_from_unit(ctx.match.slots["who"])
    metadata = list(ctx.store.by_kind(EventTime))
    if any(
        not any(
            r.kind == "cash-deposit"
            and f.provenance.sentence == r.provenance.sentence
            and f.entity == r.entity
            and f.marker == r.marker
            and f.offset == 0
            for r in deposits
        )
        for f in metadata
    ):
        return decline("an additional temporal condition lies outside the cash account")
    if (
        not quotes
        or not sales
        or not deposits
        or len(rows) + len(metadata) != len(ctx.store.facts)
        or len(rows) != len(quotes) + len(sales) + len(receipts) + len(deposits)
        or ctx.store.collisions
        or ctx.store.quarantined
        or any(r.entity_ref != who or r.provenance.assumption for r in rows)
    ):
        return decline("one complete sales and cash-transfer account is required")
    expected = defaultdict(Counter)
    amount = 0.0
    used = set()
    implicit_sources = []
    for row in rows:
        if row.value < 0:
            return decline("cash operands must be nonnegative")
        expected[row.provenance.sentence][row.value] += 1
        if row.kind == "cash-sale-quote":
            continue
        if row.kind == "cash-sale":
            matching = [
                q
                for q in quotes
                if q.container == row.measure
                and q.acquisition == row.measure
                and q.verb == row.verb
                and q.provenance.sentence < row.provenance.sentence
            ]
            if len(matching) != 1 or not float(row.value).is_integer():
                return decline(
                    "each sale needs one prior matching unit quote and a whole item count"
                )
            quote = matching[0]
            used.add(quote.key())
            value = evaluate(
                "count * price",
                {"count": row.value, "price": quote.value},
                ctx.log,
                source="cash-sale-proceeds",
            )
            unit = quote.measure
        else:
            value, unit = row.value, row.measure
        converted = convert_units(
            value,
            unit,
            ctx.query["measure"],
            ctx.reg,
            ctx.log,
            source="cash-ledger-unit",
        )
        if converted is None:
            return decline("the cash account requires compatible currencies")
        if row.kind == "cash-deposit":
            # The owner form must resolve to this account's participant.
            if (
                row.container_ref is None
                or row.container_ref.owner != who
                or not row.container_ref.resolved
            ):
                return decline("a deposit must identify its destination account owner")
            daily = False
            source = row.acquisition_ref
            if row.attribute == "owned":
                if (
                    source is None
                    or not source.resolved
                    or source.owner != who
                    or source.label
                    or len(source.qualifiers) > 1
                    or any(
                        not ctx.reg.word_in_category(q, "daily_frequency_attribute")
                        for q in source.qualifiers
                    )
                ):
                    return decline(
                        "the deposit source must be the seller’s stated proceeds"
                    )
                daily = bool(source.qualifiers)
            elif source != who:
                return decline(
                    "the deposit must belong to the cash account participant"
                )
            prior_sales = [
                s for s in sales if s.provenance.sentence < row.provenance.sentence
            ]
            if (
                not prior_sales
                or (daily and len({s.marker for s in prior_sales}) != 1)
                or (
                    row.marker
                    and any(s.marker and s.marker != row.marker for s in prior_sales)
                )
            ):
                return decline("the deposit must apply to the same preceding proceeds")
            if row.attribute == "implicit":
                implicit_sources.append(row.provenance.sentence)
            converted = -converted
        amount = evaluate(
            "cash + change",
            {"cash": amount, "change": converted},
            ctx.log,
            source="cash-on-hand",
        )
        if amount < 0:
            return decline("a transfer exceeds the available cash proceeds")
    if (
        len(used) != len(quotes)
        or uncovered_document_units(ctx.premises, ctx.question, ctx.match.consumed)
        or audit_numeric_mentions(
            (*ctx.premises, ctx.question),
            expected,
            missing="missing",
            duplicate="duplicate",
        )
    ):
        return decline(
            "all sales, receipts, transfer destinations and conditions must be read"
        )
    ctx.log.consumed_batch_keys.update(r.key() for r in rows)
    return Answer(
        "number",
        amount,
        "priced sales plus the explicit receipt, less the cash deposited; the deposit remains an owned asset",
        assumptions=(
            (
                AnswerAssumption(
                    "deposit-from-stated-proceeds",
                    "The deposit with no stated source uses the cash from the preceding sales and receipts.",
                    tuple(sorted(set(implicit_sources))),
                ),
            )
            if implicit_sources
            else ()
        ),
    )
